"""Generate a compact, shareable summary and one-row-per-match CSV."""
import collections,csv,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parent

def generate(folder=ROOT/'data'):
    folder=pathlib.Path(folder)
    def read(name):return json.loads((folder/name).read_text(encoding='utf8'))
    dataset=read('matches.json');rating=read('ratings.json');history=read('rating_history.json');mf=read('scan_manifest.json');evaluation=read('prediction_evaluation.json');seeds=read('bot_seeds.json')
    reviews={m['match_id']:m['review'] for m in history['matches']+history['excluded']};used={m['match_id'] for m in history['matches']};excluded={m['match_id']:m['reasons'] for m in history['excluded']}
    wins=collections.Counter(m['result'] for m in history['matches'])
    flags=collections.Counter(f for m in dataset['matches'] for f in m['automatic_flags'])
    summary=dict(prediction_evaluation=evaluation,seed_version=seeds['seed_version'],dataset=dataset['metadata'],ratings=rating['metadata'],rated_results=dict(wins),automatic_flag_counts=dict(flags),stop_signal_matches=sum(bool(m['review_signals']) for m in dataset['matches']),empty_files_in_period_by_filename=[r['path'] for r in mf['files'] if r['status']=='empty_or_live_recording' and pathlib.Path(r['path']).name>='2026-09-15'],ai_bonus_ratings=[r for r in rating['ratings'] if r['key'].startswith('ai:')])
    (folder/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
    with (folder/'matches_index.csv').open('w',encoding='utf-8-sig',newline='') as f:
        fields=['match_id','started_at_local','started_at_utc','map','duration_seconds','human_count','human_names','human_account_ids','ai_bonuses','observed_result','rated','exclusion_reasons','admin_thinks_cheated','exclude_from_processing','override_result','override_termination','review_signal_text','source_file']
        w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
        for m in dataset['matches']:
            w.writerow(dict(match_id=m['match_id'],started_at_local=m['started_at_local'],started_at_utc=m['started_at_utc'],map=m['map'],duration_seconds=m['duration_seconds'],human_count=len(m['players']),human_names=' | '.join(p['name'] for p in m['players']),human_account_ids=' | '.join(str(p['account_id']) for p in m['players']),ai_bonuses=' | '.join(format(p['bonus_percent'],'g') for p in m['ais']),observed_result=m['observed_outcome']['result'],rated=m['match_id'] in used,exclusion_reasons=' | '.join(excluded.get(m['match_id'],[])),admin_thinks_cheated=reviews[m['match_id']]['admin_thinks_cheated'],exclude_from_processing=reviews[m['match_id']]['exclude_from_processing'],override_result=reviews[m['match_id']]['override_result'],override_termination=reviews[m['match_id']].get('override_termination'),review_signal_text=' | '.join(s.get('text',s.get('command','')) for s in m['review_signals']),source_file=m['sources'][0]['path']))
    lines=['# BarbOS replay results','',f"Cutoff: {dataset['metadata']['cutoff']} (Pacific).",'',f"Scanned **{dataset['metadata']['source_file_count']:,}** .sdfz files. Preserved **{len(dataset['matches']):,}** qualifying match entries. Rated **{len(used):,}**; excluded **{len(excluded):,}** pending review or because the result/layout/data is unsuitable.",'',f"Rated results: **{wins['human_win']} human wins**, **{wins['ai_win']} AI wins**. Humans rated: **{rating['metadata']['human_count']:,}**.",'','SMRTBARb +50 is fixed at **mu 21, sigma 1, match rating 20** for each of the eight seats. All rated entities connect to that anchor through the match graph. Human priors are mu 25, sigma 25/3; lobby PvP ratings are preserved as context, not used as BarbOS priors.','','## Bonus levels','', 'Every bonus/configuration uses a fixed seed, sigma=1. Non-anchor seeds are provisional training estimates or explicit uncalibrated defaults. Seed sigma is an assigned parameter, not confidence that calibration is accurate.','', '| Bonus | Match rating (mu-sigma) | mu | sigma | Matches | AI wins |','|---:|---:|---:|---:|---:|---:|']
    for r in sorted(summary['ai_bonus_ratings'],key=lambda r:float(r['key'].rsplit(':',1)[1])):lines.append(f"| +{r['key'].rsplit(':',1)[1]} | {r['match_rating']:.2f}{' (fixed)' if r['fixed'] else ''} | {r['mu']:.2f} | {r['sigma']:.2f} | {r['games']} | {r['wins']} |")
    lines+=['','## Data limits','',f"{summary['stop_signal_matches']} matches have stop/cheat signals. Signals require review and do not establish wrongdoing. Four damaged gzip replays were recovered as partial match entries and excluded. Four in-period zero-byte files have no readable roster or cache and appear only in scan_manifest.json. No actual admin cheating judgments have been entered.",'','The owner supplied the shared discussion text after the first run. The primary output now implements human-only persistence and frozen versioned opponent seeds. The initial joint-learning run is preserved under data/calibration_baseline. The GitHub repository was empty; no results have been pushed.','','This is a custom anchored Plackett-Luce run, not BAR\'s official rating service or an exact reproduction of its server settings. All bot posteriors are discarded. Provisional non-anchor seeds come from a one-pass joint OpenSkill fit to the first 80% of eligible matches; their fitted latent means are retained and seed sigma set to 1. That preliminary fit uses a tied-seat approximation and is not final statistical calibration. Declared AI versions/profiles are keys, but almost all replays omit both. Unknown versions remain explicitly unknown; binary hashes cannot be recovered. Maps are retained for evaluation, not assigned separate human ratings.','','## Automatic flags','', '| Flag | Matches |','|---|---:|']
    lines += [f'| {flag} | {count} |' for flag,count in flags.most_common()]
    lines += ['', 'Counts overlap: a match may have several flags.', '', '## Forward evaluation', '', f"Seeds were calibrated on {evaluation['training_matches']} earlier eligible matches; {evaluation['holdout']['matches']} later matches were predicted before their human rating updates.", '', f"Mean predicted human win probability: {evaluation['holdout']['mean_predicted_human_win_probability']:.1%}; observed human wins: {evaluation['holdout']['observed_human_win_rate']:.1%}. Brier score: {evaluation['holdout']['brier_score']:.3f}, versus {evaluation['constant_50_percent_baseline']['brier_score']:.3f} for constant 50% predictions (lower is better).", '', f"{evaluation['uncalibrated_holdout_matches']} heldout matches used at least one uncalibrated default seed. Detailed evaluation by map, configuration, team size and probability bin is in data/prediction_evaluation.json.", '', '**These seeds are provisional and not ready for production rollout.** The forward results do not support treating the predicted win probabilities as calibrated. Full-dataset ratings include in-sample calibration games; only the later evaluation subset is held out from seed fitting.', '', 'See README.md for review fields and rerun commands.']
    (ROOT/'RESULTS.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
    print(json.dumps(dict(matches=len(dataset['matches']),rated=len(used),excluded=len(excluded),wins=dict(wins),stop_signals=summary['stop_signal_matches']),indent=2))
if __name__=='__main__':generate()
